import{_ as t,o as a,c as i,a9 as s}from"./chunks/framework.DiSH7Fw_.js";const g=JSON.parse('{"title":"Plots, notebooks and Julia tools","description":"","frontmatter":{},"headers":[],"relativePath":"interfaces/vscode-workflows.md","filePath":"interfaces/vscode-workflows.md","lastUpdated":null}'),n={name:"interfaces/vscode-workflows.md"};function o(r,e,l,d,p,h){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="Plots,-notebooks-and-Julia-tools" tabindex="-1">Plots, notebooks and Julia tools <a class="header-anchor" href="#Plots,-notebooks-and-Julia-tools" aria-label="Permalink to &quot;Plots, notebooks and Julia tools {#Plots,-notebooks-and-Julia-tools}&quot;">​</a></h1><p>Use saved evidence in full VS Code tabs, and run exploratory Julia code in an explicit notebook, terminal or debugger session. Studio links these surfaces without starting them on opening.</p><h2 id="Plot-saved-results" tabindex="-1">Plot saved results <a class="header-anchor" href="#Plot-saved-results" aria-label="Permalink to &quot;Plot saved results {#Plot-saved-results}&quot;">​</a></h2><p>Select a completed run in PerfChecker, then choose <strong>PerfChecker: Open visual output</strong>. The extension reads the saved report and opens available plots in an editor panel. Keep it beside the workload or use editor groups to compare reports.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Visual</th><th style="text-align:right;">Evidence needed</th><th style="text-align:right;">Interpretation</th></tr></thead><tbody><tr><td style="text-align:right;">Distribution</td><td style="text-align:right;">Timing/allocation samples</td><td style="text-align:right;">Spread, outliers and sample count for the recorded configuration</td></tr><tr><td style="text-align:right;">Allocation view</td><td style="text-align:right;">Allocation samples or sites</td><td style="text-align:right;">Allocation activity, with units and sampling limits</td></tr><tr><td style="text-align:right;">Flame graph</td><td style="text-align:right;">Recorded profile stacks</td><td style="text-align:right;">Sampled call-path weights; not independent timing observations</td></tr><tr><td style="text-align:right;">Version comparison</td><td style="text-align:right;">Compatible target observations</td><td style="text-align:right;">Differences against the selected baseline and aggregation policy</td></tr><tr><td style="text-align:right;">Overlay</td><td style="text-align:right;">Comparable saved series</td><td style="text-align:right;">Contrast recorded configurations without inventing missing samples</td></tr></tbody></table><p>A report without profile stacks cannot produce a measured flame graph. A missing configuration remains unmeasured. Open worker output or source from the same run if a result is incomplete.</p><p>For custom Julia figures, load <a href="./visualization">PerfCheckerMakie</a> with your chosen Makie backend. The core notebook&#39;s <code>display(bundle)</code> presents a bundle; it does not automatically create every optional graphical backend. Save reports or create figures explicitly when you need reusable plots.</p><h2 id="Investigation-notebooks" tabindex="-1">Investigation notebooks <a class="header-anchor" href="#Investigation-notebooks" aria-label="Permalink to &quot;Investigation notebooks {#Investigation-notebooks}&quot;">​</a></h2><p><strong>PerfChecker: New investigation notebook</strong> opens an untitled notebook through VS Code&#39;s built-in <code>jupyter-notebook</code> document type. Select an available <strong>Julia kernel</strong> before running cells. Notebook support and a Julia kernel provider, typically Jupyter with IJulia, must already be configured. PerfChecker does not install either.</p><p>The generated notebook contains editable cells for activating the controller, discovering the workspace, loading the scenario catalogue and measuring in the target environment, then running JET diagnostics and displaying advice.</p><p>The main Julia calls are:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">activate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(controller_project)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PerfChecker</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">discovery </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> discover</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(root)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">display</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">investigation_view</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(discovery))</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">catalog </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> load_scenario_catalog</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(catalog_path)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bundles </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> run_scenarios</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(catalog; project </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> target_project, samples </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">foreach</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(display, bundles)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">diagnosis </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> diagnose</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(catalog; project </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> target_project, tools </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:jet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">advice </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> advise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(diagnosis)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">display</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">investigation_view</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(advice))</span></span></code></pre></div><p>The generated cells fill in selected paths; the example uses explanatory variable names. Inspect the catalogue before executing measurement cells: they run all its declared cases. Proposed discovery candidates are not automatically adopted. Change the analyzer list or sample count to fit your experiment, and save the untitled notebook when you want to keep it.</p><p>JET must be installed in <code>target_project</code>. An unavailable analyzer is an explicit result; it does not establish that the program is free of inference problems.</p><p><strong>PerfChecker: Open Julia notebook</strong> opens an existing <code>.ipynb</code> in the native notebook editor. A Pluto <code>.jl</code> notebook opens as Julia source; use <a href="./repl-pluto">PerfCheckerPluto</a> for Pluto&#39;s reactive execution. PerfChecker does not convert between notebook formats.</p><h2 id="Dedicated-Julia-terminal" tabindex="-1">Dedicated Julia terminal <a class="header-anchor" href="#Dedicated-Julia-terminal" aria-label="Permalink to &quot;Dedicated Julia terminal {#Dedicated-Julia-terminal}&quot;">​</a></h2><p><strong>PerfChecker: Open Julia terminal</strong> starts a terminal named <strong>PerfChecker · package-name</strong> with:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>julia --startup-file=no --project=&lt;resolved-controller-project&gt; -i</span></span></code></pre></div><p>Its working directory is the selected package. The executable comes from <code>perfchecker.juliaExecutable</code>. A compatible existing PerfChecker terminal is reused; changing the project/executable creates a separately configured session.</p><p>Use it to inspect the public API or deliberately rerun a check. Interactive terminal state is independent from fresh measurement workers. Use saved bundle provenance for reproducibility rather than assuming the terminal matches a previous run.</p><h2 id="Julia-debugging" tabindex="-1">Julia debugging <a class="header-anchor" href="#Julia-debugging" aria-label="Permalink to &quot;Julia debugging {#Julia-debugging}&quot;">​</a></h2><p>Install the Julia VS Code extension (<code>julialang.language-julia</code>) and open a saved Julia source file belonging to the selected package. Choose <strong>PerfChecker: Debug current Julia file</strong>. PerfChecker delegates to the Julia debug adapter with the selected scenario project and stops on entry.</p><ol><li><p>Use deterministic advice to identify a workload or correctness failure.</p></li><li><p>Open its source and set a breakpoint.</p></li><li><p>Debug the file and inspect state, inputs and the oracle.</p></li><li><p>Finish debugging; rerun isolated correctness and performance checks.</p></li><li><p>Compare saved compatible results before adopting a change.</p></li></ol><p>Debugger overhead and stepping change execution. Use debugging for correctness investigation, then collect performance evidence separately. Studio&#39;s <strong>Julia extension REPL</strong> action delegates to the Julia extension&#39;s own REPL, which keeps the environment selected in Julia&#39;s status bar; check it before running code. The dedicated PerfChecker terminal uses the selected controller project and remains a separate action.</p><h2 id="Tasks-and-runners" tabindex="-1">Tasks and runners <a class="header-anchor" href="#Tasks-and-runners" aria-label="Permalink to &quot;Tasks and runners {#Tasks-and-runners}&quot;">​</a></h2><p>Studio&#39;s tasks action opens VS Code&#39;s existing task runner. Opening Studio does not create <code>tasks.json</code>. Use established package tasks or the <a href="./../reference/cli">CLI</a> for a repeatable invocation.</p><p>Suite target environments, scenario workers, native TestItems, notebooks and debug sessions serve different purposes. Select their environments explicitly. A system profiler also needs its platform/provider dependencies; see <a href="./../native-profiling">native profiling</a> and <a href="./../reference/native-external">native dependencies</a>.</p><h2 id="Etendu-and-live-3D-companions" tabindex="-1">Etendu and live 3D companions <a class="header-anchor" href="#Etendu-and-live-3D-companions" aria-label="Permalink to &quot;Etendu and live 3D companions {#Etendu-and-live-3D-companions}&quot;">​</a></h2><p>PerfChecker&#39;s public companion commands accept an explicit folder URI:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Command</th><th style="text-align:right;">Contract</th></tr></thead><tbody><tr><td style="text-align:right;"><code>perfchecker.openStudioForWorkspace(uri)</code></td><td style="text-align:right;">Open Studio for an existing workspace folder</td></tr><tr><td style="text-align:right;"><code>perfchecker.openDesignerForWorkspace(uri)</code></td><td style="text-align:right;">Open the suite designer for that folder</td></tr><tr><td style="text-align:right;"><code>perfchecker.runLandscapeLiveForWorkspace(uri, quality)</code></td><td style="text-align:right;">Run the existing live-landscape measurement workflow</td></tr></tbody></table><p>These command IDs are available to Etendu/Beautiful Landscape and other extensions. The URI must identify the intended folder in VS Code. The companion owns rendering, scene lifetime and its quality setting; PerfChecker owns the configured measurement invocation and saved evidence.</p><p>Before a live graphics comparison, keep the scene, quality, device and workload configuration comparable. A successful command or attractive scene does not establish a gain; retain the resulting evidence and its configuration.</p>`,32)])])}const k=t(n,[["render",o]]);export{g as __pageData,k as default};
